import { listActiveUsers, findUser } from '../src/services/user-service.js';
import { UserRepository } from '../src/repositories/user-repository.js';

test('listActiveUsers excludes soft-deleted users', (t, done) => {
  listActiveUsers((err, users) => {
    assert.equal(err, null);
    assert.equal(users.length, 2);
    assert.ok(users.every((u) => u.deleted_at === null));
    done();
  });
});

test('listActiveUsers reads through UserRepository and passes errors to the callback', (t, done) => {
  const boom = new Error('boom');
  const findActive = t.mock.method(UserRepository.prototype, 'findActive', () => Promise.reject(boom));
  listActiveUsers((err, users) => {
    assert.equal(findActive.mock.callCount(), 1);
    assert.equal(err, boom);
    assert.equal(users, undefined);
    done();
  });
});

